CREATE TABLE partner (
 id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(500) NOT NULL, tax_number VARCHAR(50) NOT NULL, community_tax_country VARCHAR(2), community_tax_number VARCHAR(50), registration_number VARCHAR(100), email VARCHAR(255), phone VARCHAR(100), fax VARCHAR(100), permanent_postal_code VARCHAR(20), permanent_city VARCHAR(255), permanent_public_place VARCHAR(255), permanent_public_place_type VARCHAR(100), permanent_house_number VARCHAR(50), permanent_building VARCHAR(50), permanent_staircase VARCHAR(50), permanent_floor VARCHAR(50), permanent_door VARCHAR(50), mailing_postal_code VARCHAR(20), mailing_city VARCHAR(255), mailing_public_place VARCHAR(255), mailing_public_place_type VARCHAR(100), mailing_house_number VARCHAR(50), mailing_building VARCHAR(50), mailing_staircase VARCHAR(50), mailing_floor VARCHAR(50), mailing_door VARCHAR(50), contact_name VARCHAR(255), contact_phone VARCHAR(100), contact_email VARCHAR(255), bank_name VARCHAR(255), bank_account_number VARCHAR(100), active NUMBER(1) DEFAULT 1 NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP, CONSTRAINT uk_partner_tax_number UNIQUE(tax_number));
ALTER TABLE xml_file ADD partner_id NUMBER(19);
ALTER TABLE xml_file ADD CONSTRAINT fk_xml_file_partner FOREIGN KEY(partner_id) REFERENCES partner(id);
CREATE INDEX idx_xml_file_partner ON xml_file(partner_id);
